// High-level API fixtures, generated by the built Swift library, never by the JS oracle.
import Foundation
import SpecQR

func emit(_ id: String, _ result: QRStructuredAppendResult, text: String? = nil, bytes: [UInt8]? = nil) throws {
   var object: [String: Any] = ["id": id, "parity": Int(result.parity), "total": result.total]
   if let text { object["text"] = text }
   if let bytes { object["bytes"] = bytes.map(Int.init) }
   object["symbols"] = try result.symbols.map { code -> [String: Any] in
      [
         "matrix": code.matrix.map { $0.map { $0 ? "1" : "0" }.joined() },
         "pngBase64": try code.png().base64EncodedString(),
         "dataCodewords": code.dataCodewords.map(Int.init), "ecc": code.errorCorrectionLevel.rawValue,
      ]
   }
   let data = try JSONSerialization.data(withJSONObject: object, options: [.sortedKeys])
   print(String(decoding: data, as: UTF8.self))
}
let numeric = String(repeating: "0123456789", count: 13)
try emit(
   "high-numeric",
   SpecQR.generateStructuredAppend(
      numeric,
      options: .init(qrOptions: .init(errorCorrectionLevel: .M, version: 1, mode: .numeric))), text: numeric)
