let manual: [QRSegment] = [
   .numeric("012345678901234567890123456789"), .byteText("café🙂café🙂café🙂"),
   .alphanumeric("SPECQR / 12345 "), .kanji("漢字東京大阪日本語"),
]
let manualText = "012345678901234567890123456789café🙂café🙂café🙂SPECQR / 12345 漢字東京大阪日本語"
try emit(
   "high-manual-mixed",
   SpecQR.generateSegmentsStructuredAppend(
      manual,
      options: .init(qrOptions: .init(errorCorrectionLevel: .M, version: 2))), text: manualText)
